mapper.select:
SELECT b.user_id AS id, b.user_name AS userName, b.company_id AS companyId, b.department_id AS departmentId, b.job_id AS jobId, b.email, b.job_number AS jobNumber FROM sys_eve_user_staff b
INNER JOIN tenant_user k ON k.staff_id = b.id AND k.tenant_id = #{tenantId}
b.department_id = #{departmentId}
AND b.job_id IN
#{jobId}
AND k.tenant_id = #{tenantId}
GROUP BY b.user_id

SELECT b.department_id
FROM sys_eve_user_staff b

    INNER JOIN tenant_user k ON k.staff_id = b.id AND k.tenant_id = #{tenantId}


    b.user_id = #{userId}

        AND k.tenant_id = #{tenantId}


LIMIT 1

SELECT b.id
FROM sys_eve_user_staff b

    INNER JOIN tenant_user k ON k.staff_id = b.id AND k.tenant_id = #{tenantId}


    b.user_id = #{userId}

        AND k.tenant_id = #{tenantId}


LIMIT 1

choose.when:
SELECT k.leader_staff_id
FROM tenant_user k
WHERE k.staff_id = #{staffId}
  AND k.tenant_id = #{tenantId}
LIMIT 1

